async function loginImpl(anyDb, tables, payload) {
  const email = payload.email || "";
  const password = payload.password || "";
  const useracc = await anyDb.query.accounts.findFirst({
    where: eq(tables.accounts.email, email)
  });
  if (!useracc) {
    return { status: 404, message: "Email kh\xF4ng t\u1ED3n t\u1EA1i!" };
  }
  const isPasswordValid = await bcryptjs_default.compare(password, useracc.password || "");
  if (!isPasswordValid) {
    return { status: 400, message: "M\u1EADt kh\u1EA9u kh\xF4ng \u0111\xFAng!" };
  }
  const user = await anyDb.query.users.findFirst({
    where: eq(tables.users.id, useracc.user_id)
  });
  return {
    status: 200,
    message: "\u0110\u0103ng nh\u1EADp th\xE0nh c\xF4ng!",
    user: { username: user?.fullname, email, phone: user?.phone }
  };
}
