async function sendMail2(env2, toEmail, subject, html) {
  if (env2.IS_PREVIEW === "true") {
    const token = String(env2.MAILTRAP_API_TOKEN || "");
    const inboxId = String(env2.MAILTRAP_INBOX_ID || "");
    if (token && inboxId) {
      const senderEmail = String(env2.GMAIL_SENDER_EMAIL || "no-reply@cinesphere.com.vn");
      const senderName = String(env2.GMAIL_SENDER_NAME || "CINESPHERE");
      const payload = {
        to: [{ email: toEmail }],
        from: { email: senderEmail, name: senderName },
        subject,
        html,
        category: "Review Worker Test"
      };
      const res = await fetch(`https://sandbox.api.mailtrap.io/api/send/${inboxId}`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(payload)
      });
      const bodyText = await res.text().catch(() => "");
      return {
        ok: res.ok,
        status: res.status,
        body: bodyText,
        provider: "mailtrap-sandbox",
        missing: []
      };
    }
    return {
      ok: false,
      status: 500,
      body: "Mailtrap provider is not configured for preview",
      provider: "mailtrap-sandbox",
      missing: ["MAILTRAP_API_TOKEN", "MAILTRAP_INBOX_ID"]
    };
  }
  const brevoKey = String(env2.BREVO_API_KEY || "");
  const useBrevo = Boolean(brevoKey);
  if (useBrevo) {
    const senderEmailBrevo = String(env2.BREVO_SENDER_EMAIL || "");
    const senderNameBrevo = String(env2.BREVO_SENDER_NAME || "");
    const senderEmailFallback = String(env2.GMAIL_SENDER_EMAIL || "no-reply@example.com");
    const senderNameFallback = String(env2.GMAIL_SENDER_NAME || "CTBOOKING");
    const missing = [];
    if (!brevoKey) missing.push("BREVO_API_KEY");
    if (!senderEmailBrevo) missing.push("BREVO_SENDER_EMAIL");
    if (!senderNameBrevo) missing.push("BREVO_SENDER_NAME");
    const senderEmail = senderEmailBrevo || senderEmailFallback;
    const senderName = senderNameBrevo || senderNameFallback;
    const payload = {
      sender: { email: senderEmail, name: senderName },
      to: [{ email: toEmail }],
      subject,
      htmlContent: html
    };
    const res = await fetch("https://api.brevo.com/v3/smtp/email", {
      method: "POST",
      headers: { "Content-Type": "application/json", "api-key": brevoKey },
      body: JSON.stringify(payload)
    });
    const bodyText = await res.text().catch(() => "");
    return {
      ok: res.ok,
      status: res.status,
      body: bodyText,
      provider: "brevo",
      missing
    };
  } else {
    const fromEmail = String(env2.GMAIL_SENDER_EMAIL || env2.GMAIL_USER || "no-reply@example.com");
    const fromName = String(env2.GMAIL_SENDER_NAME || "CTBOOKING");
    const missing = [];
    if (!String(env2.GMAIL_SENDER_EMAIL || env2.GMAIL_USER || "")) missing.push("GMAIL_SENDER_EMAIL");
    if (!String(env2.GMAIL_SENDER_NAME || "")) missing.push("GMAIL_SENDER_NAME");
    const payload = {
      personalizations: [{ to: [{ email: toEmail }] }],
      from: { email: fromEmail, name: fromName },
      subject,
      content: [{ type: "text/html", value: html }]
    };
    const res = await fetch("https://api.mailchannels.net/tx/v1/send", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const bodyText = await res.text().catch(() => "");
    return {
      ok: res.ok,
      status: res.status,
      body: bodyText,
      provider: "mailchannels",
      missing
    };
  }
}
