app.delete("/api/admin/site-media/:id", async (c) => {
  try {
    const id = Number(c.req.param("id"));
    const db = drizzle(c.env.cinema_db, { schema: schema_exports });
    const { deleter } = getCloudHelpers(c, c.env);
    const r = await deleteSiteMediaImpl(db, { site_media }, id, deleter);
    if (r.ok && r.item && r.item.public_id) {
      const env2 = c.env;
      const publicId = String(r.item.public_id);
      if (env2.r2_cinemastore) {
        try {
          await env2.r2_cinemastore.delete(publicId);
        } catch {
        }
      }
      if (hasCloudinary(env2)) {
        try {
          const type2 = r.item.type === "video" ? "video" : "image";
          const timestamp = Math.floor(Date.now() / 1e3);
          const params = { public_id: publicId, timestamp };
          const signed = await cloudinarySignedParams(env2, params);
          const fd = new FormData();
          fd.append("public_id", publicId);
          fd.append("timestamp", String(timestamp));
          fd.append("api_key", signed.api_key);
          fd.append("signature", signed.signature);
          const cloudName = env2.CLOUDINARY_CLOUD_NAME;
          const endpoint = `https://api.cloudinary.com/v1_1/${cloudName}/${type2}/destroy`;
          await fetch(endpoint, { method: "POST", body: fd });
        } catch {
        }
      }
    }
    const status = r?.ok ? 200 : 404;
    const payload = {
      ...r,
      status: status >= 400 ? "error" : "success"
    };
    return c.json(payload, status);
  } catch (err) {
    return c.json({ message: err?.message || "L\u1ED7i m\xE1y ch\u1EE7 n\u1ED9i b\u1ED9" }, 500);
  }
});
